begin;
set local request.jwt.claims='{"aal":"aal2"}';select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001021','updates-owner@example.test');update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000001021';
insert into public.brands(id,name) values('00000000-0000-4000-8000-000000001022','Brand aggiornamento sintetico');insert into public.seasons(id,brand_id,code,name) values('00000000-0000-4000-8000-000000001023','00000000-0000-4000-8000-000000001022','SS27','SS27');
insert into public.customers(id,legal_name,external_code,city,notes) values('00000000-0000-4000-8000-000000001024','Negozio precedente','UPD-C','Milano','Nota precedente');
insert into public.products(id,brand_id,season_id,sku_base,name,wholesale_price_cents,vat_rate) values('00000000-0000-4000-8000-000000001025','00000000-0000-4000-8000-000000001022','00000000-0000-4000-8000-000000001023','UPD-SKU','Prodotto precedente',1000,22);insert into public.product_variants(id,product_id,brand_id,size,color,sku) values('00000000-0000-4000-8000-000000001026','00000000-0000-4000-8000-000000001025','00000000-0000-4000-8000-000000001022','M','Nero','UPD-SKU-M');
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000001021';
insert into public.orders(id,brand_id,customer_id,season_id,order_date,external_ref) values('00000000-0000-4000-8000-000000001027','00000000-0000-4000-8000-000000001022','00000000-0000-4000-8000-000000001024','00000000-0000-4000-8000-000000001023','2027-01-15','UPD-O');
insert into public.order_lines(id,order_id,brand_id,variant_id,quantity,unit_price_cents,vat_rate,product_name,sku,size,color,line_net_cents,line_vat_cents) values('00000000-0000-4000-8000-000000001028','00000000-0000-4000-8000-000000001027','00000000-0000-4000-8000-000000001022','00000000-0000-4000-8000-000000001026',1,1000,0,'','','','',0,0);
insert into public.order_private(id,brand_id,internal_notes) values('00000000-0000-4000-8000-000000001027','00000000-0000-4000-8000-000000001022','Nota ordine precedente');
insert into public.budgets(id,brand_id,season_id,customer_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000001029','00000000-0000-4000-8000-000000001022','00000000-0000-4000-8000-000000001023','00000000-0000-4000-8000-000000001024',10000,'2027-01-01','2027-06-30');
insert into public.budget_private(id,brand_id,notes) values('00000000-0000-4000-8000-000000001029','00000000-0000-4000-8000-000000001022','Nota budget precedente');
update public.products set name='Prodotto catalogo aggiornato',vat_rate=10 where id='00000000-0000-4000-8000-000000001025';
select public.start_import_batch('00000000-0000-4000-8000-000000001020','mixed','updates.csv',repeat('2',64),100);insert into storage.objects(bucket_id,name,metadata) values('imports','00000000-0000-4000-8000-000000001020.csv','{"size":100}');
select public.configure_import_batch('00000000-0000-4000-8000-000000001020','{"revision":"00000000-0000-4000-8000-000000001030","profiles":[{"entity":"customers","sheet_name":"Negozi","header_row":1,"mapping":{},"options":{"mode":"upsert"}},{"entity":"orders","sheet_name":"Ordini","header_row":1,"mapping":{},"options":{"mode":"upsert","granularity":"order_lines","initialStatus":"draft"}},{"entity":"budgets","sheet_name":"Budget","header_row":1,"mapping":{},"options":{"mode":"upsert"}}]}','{}',null);
select public.stage_import_rows('00000000-0000-4000-8000-000000001020','[{"entity":"customers","sheet":"Negozi","row_number":2,"raw":{},"mapped":{"legal_name":"Negozio aggiornato","external_code":"UPD-C","city":"Milano","notes":"Nuova nota"},"status":"valid"},{"entity":"orders","sheet":"Ordini","row_number":2,"raw":{},"mapped":{"external_ref":"UPD-O","customer":"UPD-C","brand":"Brand aggiornamento sintetico","season":"SS27","order_date":"2027-01-15","sku":"UPD-SKU-M","quantity":2,"unit_price_cents":1500,"discount_pct":10,"notes":"Nuova nota ordine"},"status":"valid"},{"entity":"budgets","sheet":"Budget","row_number":2,"raw":{},"mapped":{"customer":"UPD-C","brand":"Brand aggiornamento sintetico","season":"SS27","period_start":"2027-01-01","period_end":"2027-06-30","amount_cents":50000,"notes":"Nuova nota budget"},"status":"valid"}]','00000000-0000-4000-8000-000000001030');
select public.finish_import_staging('00000000-0000-4000-8000-000000001020','00000000-0000-4000-8000-000000001030','{"Negozi":1,"Ordini":1,"Budget":1}');
select public.resolve_import_match('00000000-0000-4000-8000-000000001020','customer','["UPD-C","","Negozio aggiornato","Milano",""]','{"action":"link","type":"existing","id":"00000000-0000-4000-8000-000000001024"}','00000000-0000-4000-8000-000000001030');
select public.resolve_import_match('00000000-0000-4000-8000-000000001020','customer','["UPD-C","","","",""]','{"action":"link","type":"existing","id":"00000000-0000-4000-8000-000000001024"}','00000000-0000-4000-8000-000000001030');
select public.resolve_import_match('00000000-0000-4000-8000-000000001020','brand','["Brand aggiornamento sintetico"]','{"action":"link","type":"existing","id":"00000000-0000-4000-8000-000000001022"}','00000000-0000-4000-8000-000000001030');
select public.resolve_import_match('00000000-0000-4000-8000-000000001020','season','["Brand aggiornamento sintetico","SS27"]','{"action":"link","type":"existing","id":"00000000-0000-4000-8000-000000001023"}','00000000-0000-4000-8000-000000001030');
select public.resolve_import_match('00000000-0000-4000-8000-000000001020','variant','["Brand aggiornamento sintetico","SS27","UPD-SKU-M"]','{"action":"link","type":"existing","id":"00000000-0000-4000-8000-000000001026"}','00000000-0000-4000-8000-000000001030');
select is(public.import_preview('00000000-0000-4000-8000-000000001020')->>'problem_count','0','update preview valid');
select ok(jsonb_array_length(public.import_preview('00000000-0000-4000-8000-000000001020')->'operations'->0->'changes')>0,'field differences visible before update');
select lives_ok($$select public.import_commit('00000000-0000-4000-8000-000000001020',true,false)$$,'upsert existing records atomically');
select is((select net_total_cents from public.orders where id='00000000-0000-4000-8000-000000001027'),2700::bigint,'updated order net');
select is((select vat_total_cents from public.orders where id='00000000-0000-4000-8000-000000001027'),270::bigint,'new line uses current catalog tax snapshot');
select is((select amount_cents from public.budgets where id='00000000-0000-4000-8000-000000001029'),50000::bigint,'existing budget updated');
select lives_ok($$select public.import_rollback('00000000-0000-4000-8000-000000001020')$$,'rollback restores pre-import snapshots');
select is((select legal_name from public.customers where id='00000000-0000-4000-8000-000000001024'),'Negozio precedente','customer restored');
select is((select amount_cents from public.budgets where id='00000000-0000-4000-8000-000000001029'),10000::bigint,'budget restored');
select is((select notes from public.budget_private where id='00000000-0000-4000-8000-000000001029'),'Nota budget precedente','private budget note restored');
select is((select net_total_cents from public.orders where id='00000000-0000-4000-8000-000000001027'),1000::bigint,'original order net restored');
select is((select vat_total_cents from public.orders where id='00000000-0000-4000-8000-000000001027'),220::bigint,'original historic tax snapshot restored despite changed catalog');
select is((select product_name from public.order_lines where id='00000000-0000-4000-8000-000000001028'),'Prodotto precedente','original historic product snapshot restored');
select is((select internal_notes from public.order_private where id='00000000-0000-4000-8000-000000001027'),'Nota ordine precedente','private order note restored');
select is(public.import_totals('00000000-0000-4000-8000-000000001020')->0->>'net_cents','2700','report preserves imported total after restoring old order');
select is(public.import_batch_report('00000000-0000-4000-8000-000000001020')->'budgets'->0->>'budget_cents','50000','report preserves budget snapshot after rollback');
select is(public.import_batch_report('00000000-0000-4000-8000-000000001020')->'budgets'->0->>'sold_cents',null,'missing previous season is unknown not zero');
select * from finish();rollback;
